"""Data quality: fifteen distinct reconciliation and survivorship tasks."""
from _draft_helpers import topic

S = """
CREATE TABLE raw_customer(id INTEGER PRIMARY KEY,name TEXT,email TEXT,city TEXT);
INSERT INTO raw_customer VALUES
 (1,' Ann ','A@EXAMPLE.COM','NY'),(2,'Ann','a@example.com',NULL),
 (3,'Bob','b@example.com','LA'),(4,' ',NULL,'LA'),(5,'Cara','bad','NY');
CREATE TABLE payment(id INTEGER PRIMARY KEY,customer_id INTEGER,amount INTEGER);
INSERT INTO payment VALUES (1,1,20),(2,1,30),(3,3,-4),(4,99,10),(5,5,0);
CREATE TABLE feed(id INTEGER PRIMARY KEY,email TEXT);
INSERT INTO feed VALUES (1,'a@example.com'),(3,'changed@example.com'),(6,'d@example.com');
"""

def T(n,slug,title,concepts,explain,q,out,pitfalls,a,b):
    return topic(n,slug,title,"quality",concepts,explain,S,q,out,pitfalls,a,b)

LESSONS = [
 T(127,"canonical-email-duplicates","规范化邮箱后识别重复客户",["LOWER","TRIM","业务键"],
   "先去除邮箱两端空白并转小写，再按规范键分组。前两行虽然存储文本不同，却代表同一邮箱，因此重复组为 a@example.com、数量 2。规范化是业务规则，不能擅自应用到区分大小写的标识符。",
   "SELECT lower(trim(email)),count(*) FROM raw_customer WHERE email IS NOT NULL GROUP BY lower(trim(email)) HAVING count(*)>1 ORDER BY 1;",
   "a@example.com|2",["NULL 不是可用邮箱键。","规范化前分组会漏掉大小写重复。"],
   ("列出重复邮箱对应的原始 id。","用相关 EXISTS 比较规范键并排除自己。","SELECT a.id FROM raw_customer a WHERE a.email IS NOT NULL AND EXISTS(SELECT 1 FROM raw_customer b WHERE b.id<>a.id AND lower(trim(b.email))=lower(trim(a.email))) ORDER BY a.id;","1\n2"),
   ("统计非空邮箱的不同规范键数量。","COUNT DISTINCT 忽略 NULL。","SELECT count(DISTINCT lower(trim(email))) FROM raw_customer;","3")),
 T(128,"field-completeness","按字段统计缺失率的分母",["NULLIF","条件聚合","完整性"],
   "把去空白后的空姓名视为缺失，邮箱与城市按 NULL 判断。五行中姓名缺失 1、邮箱缺失 1、城市缺失 1；三个计数不是三位不同客户。显式返回总行数，避免把字段缺失误算成客户缺失。",
   "SELECT count(*),sum(nullif(trim(name),'') IS NULL),sum(email IS NULL),sum(city IS NULL) FROM raw_customer;",
   "5|1|1|1",["空白字符串不会被 IS NULL 识别。","各字段缺失数不能直接相加当作缺失人数。"],
   ("找出任意一个字段缺失的客户。","字段条件使用 OR。","SELECT id FROM raw_customer WHERE nullif(trim(name),'') IS NULL OR email IS NULL OR city IS NULL ORDER BY id;","2\n4"),
   ("计算三个字段均完整的客户数。","完整条件使用 AND。","SELECT count(*) FROM raw_customer WHERE nullif(trim(name),'') IS NOT NULL AND email IS NOT NULL AND city IS NOT NULL;","3")),
 T(129,"orphan-reference-report","孤儿付款的金额对账",["反连接","引用完整性","对账"],
   "从付款保留全量，左连客户并检查客户主键为空，可找出 customer_id=99 的孤儿。报告同时保留付款主键和金额 10，方便修复来源；不能只统计数量而丢掉金额风险。",
   "SELECT p.id,p.customer_id,p.amount FROM payment p LEFT JOIN raw_customer c ON c.id=p.customer_id WHERE c.id IS NULL ORDER BY p.id;",
   "4|99|10",["应检查非空主键，不能检查本来可空的 city。","内连接会直接隐藏孤儿记录。"],
   ("统计能够找到客户的付款金额。","EXISTS 不会放大付款行。","SELECT sum(amount) FROM payment p WHERE EXISTS(SELECT 1 FROM raw_customer c WHERE c.id=p.customer_id);","46"),
   ("找出没有任何付款的客户 id。","以客户为起点使用 NOT EXISTS。","SELECT c.id FROM raw_customer c WHERE NOT EXISTS(SELECT 1 FROM payment p WHERE p.customer_id=c.id) ORDER BY c.id;","2\n4")),
 T(130,"domain-rule-failures","为金额异常生成可解释原因",["CASE","业务约束","异常分类"],
   "负金额、零金额和孤儿引用属于不同问题，应分别分类。这里仅分类金额：付款 3 为负数，付款 5 为零；WHERE 保留失败记录，CASE 生成便于导出的问题说明。零是否异常必须由业务定义。",
   "SELECT id,CASE WHEN amount<0 THEN 'negative' ELSE 'zero' END FROM payment WHERE amount<=0 ORDER BY id;",
   "3|negative\n5|zero",["退款业务可能允许负数，不能无条件删除。","CASE 分支顺序应覆盖最具体条件。"],
   ("计算正金额付款数及总金额。","先过滤 amount>0。","SELECT count(*),sum(amount) FROM payment WHERE amount>0;","3|60"),
   ("找出同时金额为正且客户存在的付款。","结合金额规则与 EXISTS。","SELECT p.id FROM payment p WHERE amount>0 AND EXISTS(SELECT 1 FROM raw_customer c WHERE c.id=p.customer_id) ORDER BY p.id;","1\n2")),
 T(131,"source-reconciliation","全连接区分新增删除和修改",["FULL OUTER JOIN","变更对账","NULL 比较"],
   "按稳定 id 全连接本地客户和导入源，分别识别 only_local、only_feed 与 changed。id=3 两边都有但邮箱不同；2、4、5 仅本地存在，6 仅导入存在。IS NOT 支持 NULL 安全比较，避免三值逻辑漏报。",
   "SELECT coalesce(c.id,f.id),CASE WHEN c.id IS NULL THEN 'only_feed' WHEN f.id IS NULL THEN 'only_local' ELSE 'changed' END FROM raw_customer c FULL OUTER JOIN feed f ON c.id=f.id WHERE c.id IS NULL OR f.id IS NULL OR lower(c.email) IS NOT lower(f.email) ORDER BY 1;",
   "2|only_local\n3|changed\n4|only_local\n5|only_local\n6|only_feed",["SQLite FULL OUTER JOIN 需要 3.39 及以上。","不要用 <> 比较可空值的变化。"],
   ("仅返回两边都有且邮箱发生变化的 id。","内连接后使用 IS NOT。","SELECT c.id FROM raw_customer c JOIN feed f ON c.id=f.id WHERE lower(c.email) IS NOT lower(f.email) ORDER BY c.id;","3"),
   ("仅返回导入新增 id。","从 feed 使用 NOT EXISTS。","SELECT f.id FROM feed f WHERE NOT EXISTS(SELECT 1 FROM raw_customer c WHERE c.id=f.id) ORDER BY f.id;","6")),
 T(132,"survivor-record","为重复业务键选择确定的保留行",["ROW_NUMBER","存续规则","去重"],
   "同一规范邮箱内先保留城市非空的行，再按最小 id 打破并列。这样重复的 Ann 保留 id=1，另外保留 Bob 与 Cara；缺失邮箱被显式排除。去重查询只是候选集，不执行删除。",
   "WITH r AS (SELECT id,row_number() OVER(PARTITION BY lower(email) ORDER BY city IS NULL,id) rn FROM raw_customer WHERE email IS NOT NULL) SELECT id FROM r WHERE rn=1 ORDER BY id;",
   "1\n3\n5",["没有稳定的最终排序键会导致保留行漂移。","缺失业务键不应自动合并成一个客户。"],
   ("输出有邮箱但没有被保留的行。","复用排名并筛选 rn>1。","WITH r AS (SELECT id,row_number() OVER(PARTITION BY lower(email) ORDER BY city IS NULL,id) rn FROM raw_customer WHERE email IS NOT NULL) SELECT id FROM r WHERE rn>1 ORDER BY id;","2"),
   ("找出同邮箱组中城市尚待补全的行。","用同组另一行提供城市。","SELECT a.id,b.city FROM raw_customer a JOIN raw_customer b ON lower(a.email)=lower(b.email) AND a.id<>b.id WHERE a.city IS NULL AND b.city IS NOT NULL ORDER BY a.id,b.id;","2|NY")),
 T(133,"aggregate-before-join","先聚合付款避免客户计数膨胀",["粒度","预聚合","一对多"],
   "付款先按 customer_id 汇总，再连接客户，每位客户只出现一次。Ann 的两笔为 50，Bob 为 -4，Cara 为 0，没有付款的客户补 0。汇总层隔离了一对多关系，后续客户数量才有明确含义。",
   "WITH p AS (SELECT customer_id,sum(amount) total FROM payment GROUP BY customer_id) SELECT c.id,coalesce(p.total,0) FROM raw_customer c LEFT JOIN p ON p.customer_id=c.id ORDER BY c.id;",
   "1|50\n2|0\n3|-4\n4|0\n5|0",["直接连接后 COUNT(*) 统计的是连接行而非客户。","补零会混淆无付款和净额恰为零，必要时保留笔数。"],
   ("分别统计客户总数及有付款的客户数。","聚合付款后对连接键计数。","WITH p AS (SELECT DISTINCT customer_id FROM payment) SELECT count(*),count(p.customer_id) FROM raw_customer c LEFT JOIN p ON p.customer_id=c.id;","5|3"),
   ("返回付款净额大于零的客户 id。","先按客户分组，再 HAVING。","SELECT customer_id FROM payment WHERE customer_id IN(SELECT id FROM raw_customer) GROUP BY customer_id HAVING sum(amount)>0 ORDER BY customer_id;","1")),
 T(134,"distinct-name-vs-id","显示名重复与实体重复的区别",["业务实体","DISTINCT","规范姓名"],
   "姓名只用于展示，不能替代客户主键。去空白后 Ann 对应两个不同 id，查询返回规范名、记录数及最小最大 id；这证明需要检查业务键，而不是看到同名就合并实体。",
   "SELECT trim(name),count(*),min(id),max(id) FROM raw_customer GROUP BY trim(name) HAVING count(*)>1 ORDER BY 1;",
   "Ann|2|1|2",["同名客户可能是不同人。","TRIM 默认不处理所有 Unicode 空白。"],
   ("统计非空的不同显示名数量。","先 NULLIF 再 COUNT DISTINCT。","SELECT count(DISTINCT nullif(trim(name),'')) FROM raw_customer;","3"),
   ("列出姓名需要去除首尾空格的原始 id。","原值与 TRIM 值比较。","SELECT id FROM raw_customer WHERE name<>trim(name) ORDER BY id;","1\n4")),
 T(135,"email-shape-audit","邮箱形状检查的能力边界",["INSTR","局部规则","数据清洗"],
   "本地形状检查只要求 @ 前有字符、@ 后有点，不声称验证完整邮箱标准。bad 与 NULL 都不符合规则，所以返回 4、5。将规则用于导入提示比把它当作邮件可达性证明更准确。",
   "SELECT id FROM raw_customer WHERE email IS NULL OR instr(email,'@')<=1 OR instr(substr(email,instr(email,'@')+1),'.')=0 ORDER BY id;",
   "4\n5",["字符串规则不能证明邮箱可投递。","NULL 应单独处理，否则 WHERE 会丢掉未知值。"],
   ("提取满足本课规则的邮箱域名。","从 @ 后截取并转小写。","SELECT id,lower(substr(email,instr(email,'@')+1)) FROM raw_customer WHERE instr(email,'@')>1 AND instr(substr(email,instr(email,'@')+1),'.')>0 ORDER BY id;","1|example.com\n2|example.com\n3|example.com"),
   ("按可用域名统计原始记录数。","使用同样规则保持分母一致。","SELECT lower(substr(email,instr(email,'@')+1)),count(*) FROM raw_customer WHERE instr(email,'@')>1 AND instr(substr(email,instr(email,'@')+1),'.')>0 GROUP BY 1 ORDER BY 1;","example.com|3")),
 T(136,"reconciliation-control-totals","对账控制总数与金额守恒",["控制总额","UNION ALL","差异"],
   "全部付款净额为 56，其中客户存在的净额 46、孤儿净额 10，二者相加回到总额。用三个命名口径输出，比仅看行数更容易发现负数或漏连造成的账差。UNION ALL 保留每个口径。",
   "SELECT 'all',sum(amount) FROM payment UNION ALL SELECT 'matched',sum(amount) FROM payment WHERE customer_id IN(SELECT id FROM raw_customer) UNION ALL SELECT 'orphan',sum(amount) FROM payment WHERE customer_id NOT IN(SELECT id FROM raw_customer);",
   "all|56\nmatched|46\norphan|10",["NOT IN 的子查询必须保证不含 NULL。","控制总额应包括负数和零，不能只加正数。"],
   ("返回匹配与孤儿金额之和减去总额的差。","每行用 CASE 分类，差应为零。","SELECT sum(CASE WHEN customer_id IN(SELECT id FROM raw_customer) THEN amount ELSE 0 END)+sum(CASE WHEN customer_id NOT IN(SELECT id FROM raw_customer) THEN amount ELSE 0 END)-sum(amount) FROM payment;","0"),
   ("同时列出付款行数和非零付款行数。","COUNT 与条件 SUM 分开。","SELECT count(*),sum(amount<>0) FROM payment;","5|4")),
 T(137,"cross-field-invariant","跨字段规则而非单列非空检查",["交叉校验","CASE","业务不变量"],
   "导入审批要求有有效显示名且有邮箱，城市缺失可稍后补录。id=2 因而仍可用，id=4 被拒绝；此规则与三字段全部完整不同。可解释状态让用户知道是哪条要求影响审批。",
   "SELECT id,CASE WHEN nullif(trim(name),'') IS NULL THEN 'missing_name' WHEN email IS NULL THEN 'missing_email' ELSE 'ready' END FROM raw_customer ORDER BY id;",
   "1|ready\n2|ready\n3|ready\n4|missing_name\n5|ready",["CASE 只返回首个匹配原因，全部原因需另建规则表。","有邮箱不代表满足完整邮箱规范。"],
   ("按审批规则统计可用记录数。","姓名与邮箱使用 AND。","SELECT count(*) FROM raw_customer WHERE nullif(trim(name),'') IS NOT NULL AND email IS NOT NULL;","4"),
   ("列出审批可用但城市仍缺失的 id。","可用条件后再检查 city。","SELECT id FROM raw_customer WHERE nullif(trim(name),'') IS NOT NULL AND email IS NOT NULL AND city IS NULL ORDER BY id;","2")),
 T(138,"rule-results-unpivot","将宽字段质量结果转换为问题清单",["UNION ALL","反透视","规则清单"],
   "用多个规则查询纵向拼接同一条记录的所有问题，形成 id、rule 两列。id=4 同时缺姓名和邮箱，因此保留两行；UNION ALL 不会把独立规则意外合并。这种结构方便问题面板逐项导航。",
   "SELECT id,'name' rule FROM raw_customer WHERE nullif(trim(name),'') IS NULL UNION ALL SELECT id,'email' FROM raw_customer WHERE email IS NULL UNION ALL SELECT id,'city' FROM raw_customer WHERE city IS NULL ORDER BY id,rule;",
   "2|city\n4|email\n4|name",["问题条数与受影响记录数是不同指标。","规则名应稳定，便于后续统计和修复。"],
   ("只计算受影响的不同客户数量。","将问题集包进 CTE，再 COUNT DISTINCT。","WITH issues AS(SELECT id FROM raw_customer WHERE nullif(trim(name),'') IS NULL UNION ALL SELECT id FROM raw_customer WHERE email IS NULL UNION ALL SELECT id FROM raw_customer WHERE city IS NULL) SELECT count(DISTINCT id) FROM issues;","2"),
   ("返回每位客户有几个缺失字段。","将布尔结果相加。","SELECT id,(nullif(trim(name),'') IS NULL)+(email IS NULL)+(city IS NULL) n FROM raw_customer WHERE n>0 ORDER BY id;","2|1\n4|2")),
 T(139,"categorical-domain-audit","参照字典查找未知分类值",["VALUES","字典","反连接"],
   "允许的城市字典只有 NY，LA 因而是未知分类，而 NULL 属于缺失分类，单独排除。用参照集合比散落多个不等式更容易维护，也能保留原始值供人工映射。这里找出 id=3、4。",
   "WITH allowed(city) AS(VALUES('NY')) SELECT id,city FROM raw_customer c WHERE city IS NOT NULL AND NOT EXISTS(SELECT 1 FROM allowed a WHERE a.city=c.city) ORDER BY id;",
   "3|LA\n4|LA",["未知与缺失应分开统计。","字典是否区分大小写要由业务明确。"],
   ("统计 NY、其他非空、缺失三种状态。","CASE 分桶后分组。","SELECT CASE WHEN city IS NULL THEN 'missing' WHEN city='NY' THEN 'allowed' ELSE 'unknown' END status,count(*) FROM raw_customer GROUP BY status ORDER BY status;","allowed|2\nmissing|1\nunknown|2"),
   ("输出已有城市字典及各自记录数。","排除 NULL，再分组。","SELECT city,count(*) FROM raw_customer WHERE city IS NOT NULL GROUP BY city ORDER BY city;","LA|2\nNY|2")),
 T(140,"null-safe-feed-comparison","用 NULL 安全相等定义未变化记录",["IS","可空属性","导入比较"],
   "两边都有的客户为 1 和 3，邮箱转小写后 id=1 相等、id=3 不等。IS 把 NULL 对 NULL 视为相等，适合比较快照属性；此处的稳定键仍然是 id，绝不能把可空邮箱当连接键。",
   "SELECT c.id,lower(c.email) IS lower(f.email) same_email FROM raw_customer c JOIN feed f ON c.id=f.id ORDER BY c.id;",
   "1|1\n3|0",["IS 的 NULL 语义与 = 不同。","大小写规范化属于比较策略，不是自动修改存储值。"],
   ("返回源中与本地完全匹配的 id。","IS 用于过滤匹配属性。","SELECT f.id FROM feed f JOIN raw_customer c ON c.id=f.id WHERE lower(c.email) IS lower(f.email) ORDER BY f.id;","1"),
   ("返回源中需要新增或更新的 id。","缺失本地主键或属性不等。","SELECT f.id FROM feed f LEFT JOIN raw_customer c ON c.id=f.id WHERE c.id IS NULL OR lower(c.email) IS NOT lower(f.email) ORDER BY f.id;","3\n6")),
 T(141,"multi-rule-scorecard","一次扫描构建质量规则记分卡",["FILTER","条件聚合","质量报表"],
   "FILTER 让同一次聚合分别计算全量、正金额、负金额与零金额付款数量，结果 5、3、1、1。各类别互斥并覆盖非空金额，能够直接核对类别数之和。只需要数量时不必生成多个临时表。",
   "SELECT count(*),count(*) FILTER(WHERE amount>0),count(*) FILTER(WHERE amount<0),count(*) FILTER(WHERE amount=0) FROM payment;",
   "5|3|1|1",["若金额允许 NULL，还需加入未知类别。","COUNT(amount) 会忽略 NULL，COUNT(*) 不会。"],
   ("在同一行输出正额和负额合计。","SUM 使用不同 FILTER。","SELECT sum(amount) FILTER(WHERE amount>0),sum(amount) FILTER(WHERE amount<0) FROM payment;","60|-4"),
   ("返回非正金额占全部付款的百分比。","用 100.0 避免整数除法。","SELECT round(100.0*count(*) FILTER(WHERE amount<=0)/count(*),1) FROM payment;","40.0")),
]
